int kthreadd(void *unused)
{
	struct task_struct *tsk = current;

	/* Setup a clean context for our children to inherit. */
	set_task_comm(tsk, "kthreadd");
	ignore_signals(tsk);
	set_cpus_allowed_ptr(tsk, housekeeping_cpumask(HK_TYPE_KTHREAD));
	set_mems_allowed(node_states[N_MEMORY]);

	current->flags |= PF_NOFREEZE;
	cgroup_init_kthreadd();

	for (;;) {
		set_current_state(TASK_INTERRUPTIBLE);
		if (list_empty(&kthread_create_list)
#ifdef CONFIG_LSF_STREAM_FACTORY
		    && !READ_ONCE(lsf_cleanup_pending)
		    && !lsf_factory_cleanup_retire_pending()
		    && !lsf_prepaid_cleanup_irq_pending()
		    && !lsf_factory_cleanup_final_pending()
		    && !lsf_factory_cleanup_request_pending()
#endif
		   )
			schedule();
		__set_current_state(TASK_RUNNING);

		spin_lock(&kthread_create_lock);
		while (!list_empty(&kthread_create_list)
#ifdef CONFIG_LSF_STREAM_FACTORY
		       || lsf_cleanup_pending || lsf_factory_cleanup_retire_pending()
		       || lsf_prepaid_cleanup_irq_pending()
		       || lsf_factory_cleanup_final_pending()
		       || lsf_factory_cleanup_request_pending()
#endif
		      ) {
#ifdef CONFIG_LSF_STREAM_FACTORY
			if (lsf_factory_cleanup_request_pending()) {
				spin_unlock(&kthread_create_lock);
				lsf_factory_cleanup_request_drain();
				spin_lock(&kthread_create_lock);
				continue;
			}
			if (lsf_factory_cleanup_final_pending()) {
				spin_unlock(&kthread_create_lock);
				lsf_factory_cleanup_final_drain();
				spin_lock(&kthread_create_lock);
				continue;
			}
			if (lsf_prepaid_cleanup_irq_pending()) {
				spin_unlock(&kthread_create_lock);
				lsf_prepaid_cleanup_irq_drain();
				spin_lock(&kthread_create_lock);
				continue;
			}
			if (lsf_factory_cleanup_retire_pending()) {
				spin_unlock(&kthread_create_lock);
				lsf_prepaid_cleanup_retire_one();
				spin_lock(&kthread_create_lock);
				continue;
			}
			if (lsf_cleanup_pending) {
				struct lsf_cleanup_request *owned = lsf_cleanup_pending;
				WRITE_ONCE(lsf_cleanup_pending, NULL);
				spin_unlock(&kthread_create_lock);
				lsf_cleanup_dispatch_kthread(owned);
				spin_lock(&kthread_create_lock);
				continue;
			}
#endif
			struct kthread_create_info *create;

			create = list_entry(kthread_create_list.next,
					    struct kthread_create_info, list);
			list_del_init(&create->list);
			spin_unlock(&kthread_create_lock);

			create_kthread(create);

			spin_lock(&kthread_create_lock);
		}
		spin_unlock(&kthread_create_lock);
	}

	return 0;
}
